rollback.sql:
DO $do$
DECLARE
    actor CONSTANT VARCHAR := 'sprint87-retire-modeling-layer-groups';
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('dts:portal-menu:retire-modeling-layer-groups:20260810-02', 0));

    UPDATE portal_menu
       SET deleted = FALSE,
           last_modified_by = actor || '-rollback',
           last_modified_date = now()
     WHERE deleted = TRUE
       AND last_modified_by = actor || '-retired';
END $do$;
